#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> datos{1, 2, 15};
    double suma = 0.0;
    for (int valor : datos) { suma += valor; }
    double media = suma / static_cast<double>(datos.size());
    auto ordenados = datos;
    std::sort(ordenados.begin(), ordenados.end());
    double mediana = ordenados.at(ordenados.size() / 2);
    std::cout << media << " " << mediana;
    return 0;
}

